+            <li>Push notifications keep updates visible inside the app experience.</li>
+          </ul>
+        </aside>
+      `;
+    }
+
+    function App() {
+      return PageShell(`
+        <div class="layout">
+          ${FormCard()}
+          ${InfoPanel()}
+        </div>
+      `);
+    }
+
+    function setGroupInvalidState(isInvalid) {
+      document.querySelectorAll('input[name="notificationPreference"]').forEach((radio) => {
+        if (isInvalid) {
+          radio.setAttribute("aria-invalid", "true");
+        } else {
+          radio.removeAttribute("aria-invalid");
+        }
+      });
+    }
+
+    function showError() {
+      const error = document.getElementById("notification-error");
+      const status = document.getElementById("form-status");
+      error.hidden = false;
+      status.textContent = "Please choose one notification method before saving.";
+      status.dataset.state = "error";
+      setGroupInvalidState(true);
+      const firstRadio = document.querySelector('input[name="notificationPreference"]');
+      if (firstRadio) {
+        firstRadio.focus();
+      }
+    }
+
+    function clearError() {
+      const error = document.getElementById("notification-error");
+      if (!error.hidden) {
+        error.hidden = true;
+      }
+      setGroupInvalidState(false);
+    }
+
+    function showSuccess(value) {
+      const status = document.getElementById("form-status");
+      status.textContent = `Preference saved: ${value}.`;
+      status.dataset.state = "success";
+    }
+
+    function bindForm() {
+      const form = document.getElementById("preferences-form");
+      const radios = document.querySelectorAll('input[name="notificationPreference"]');
+
+      radios.forEach((radio) => {
+        radio.addEventListener("change", () => {
+          clearError();
+          const status = document.getElementById("form-status");
+          status.textContent = "";
+          status.dataset.state = "";
+        });
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        const selected = document.querySelector('input[name="notificationPreference"]:checked');
+
+        if (!selected) {
+          showError();
+          return;
+        }
+
+        clearError();
+        showSuccess(selected.value);
+      });
+    }
+
+    document.getElementById("app").innerHTML = App();
+    bindForm();
+  </script>
+</body>
+</html>
*** End Patch
