<body>
  <div id="app"></div>

  <script>
    const options = [
      { id: "notification-email", value: "Email", label: "Email" },
      { id: "notification-sms", value: "SMS", label: "SMS" },
      { id: "notification-push", value: "Push Notifications", label: "Push Notifications" }
    ];

    function PageShell(content) {
      return `
        <a class="skip-link" href="#maincontent">Skip to main content</a>
        <header class="page-shell hero">
          <p class="eyebrow">Preferences</p>
        </header>
        <main id="maincontent" tabindex="-1" class="page-shell">
          ${content}
        </main>
      `;
    }

    function RadioOption(option) {
      return `
        <div class="radio-option">
          <input
            id="${option.id}"
            type="radio"
            name="notificationPreference"
            value="${option.value}"
            required
          >
          <label for="${option.id}">${option.label}</label>
        </div>
      `;
    }

    function NotificationQuestion() {
      return `
        <div class="form-field">
          <fieldset id="notification-group" aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-indicator" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="form-help">
              Select one option to choose how account updates and alerts should reach you.
            </p>
            <div class="radio-list">
              ${options.map(RadioOption).join("")}
            </div>
            <p id="notification-error" class="form-error" hidden>
              Error: Select how you prefer to receive notifications.
            </p>
          </fieldset>
        </div>
      `;
    }

    function FormCard() {
      return `
        <section class="card" aria-labelledby="form-title">
          <div class="card-header">
            <h1 id="form-title">Notification settings</h1>
            <p>Choose a single delivery channel for product news, reminders, and important updates.</p>
          </div>
          <form id="preferences-form" novalidate>
            <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required field</p>
            ${NotificationQuestion()}
            <button class="submit-button" type="submit">Save preference</button>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </form>
        </section>
      `;
    }

    function InfoPanel() {
      return `
        <aside class="info-panel" aria-labelledby="details-title">
          <h2 id="details-title">What happens next</h2>
          <p>Your selected channel becomes the default for future account messages.</p>
          <ul class="info-list">
            <li>Email works well for summaries and account receipts.</li>
            <li>SMS is ideal for urgent alerts while you're on the go.</li>
            <li>Push notifications keep updates visible inside the app experience.</li>
          </ul>
        </aside>
      `;
    }

    function App() {
      return PageShell(`
        <div class="layout">
          ${FormCard()}
          ${InfoPanel()}
        </div>
      `);
    }

    function setGroupInvalidState(isInvalid) {
      document.querySelectorAll('input[name="notificationPreference"]').forEach((radio) => {
        if (isInvalid) {
          radio.setAttribute("aria-invalid", "true");
        } else {
          radio.removeAttribute("aria-invalid");
        }
      });
    }

    function updateGroupDescription(showError) {
      const fieldset = document.getElementById("notification-group");
      fieldset.setAttribute(
        "aria-describedby",
        showError ? "notification-help notification-error" : "notification-help"
      );
    }

    function showError() {
      const error = document.getElementById("notification-error");
      const status = document.getElementById("form-status");
      error.hidden = false;
      updateGroupDescription(true);
      status.textContent = "Please choose one notification method before saving.";
      status.dataset.state = "error";
      setGroupInvalidState(true);
      const firstRadio = document.querySelector('input[name="notificationPreference"]');
      if (firstRadio) {
        firstRadio.focus();
      }
    }

    function clearError() {
      const error = document.getElementById("notification-error");
      if (!error.hidden) {
        error.hidden = true;
      }
      updateGroupDescription(false);
      setGroupInvalidState(false);
    }

    function showSuccess(value) {
      const status = document.getElementById("form-status");
      status.textContent = `Preference saved: ${value}.`;
      status.dataset.state = "success";
    }

    function bindForm() {
      const form = document.getElementById("preferences-form");
      const radios = document.querySelectorAll('input[name="notificationPreference"]');

      radios.forEach((radio) => {
        radio.addEventListener("change", () => {
          clearError();
          const status = document.getElementById("form-status");
          status.textContent = "";
          status.dataset.state = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selected = document.querySelector('input[name="notificationPreference"]:checked');

        if (!selected) {
          showError();
          return;
        }

        clearError();
        showSuccess(selected.value);
      });
    }

    document.getElementById("app").innerHTML = App();
    bindForm();
  </script>
</body>
</html>
