 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Notification preferences - Account settings</title>
   <style>
     :root {
       color-scheme: light dark;
       --bg: #f4f7fb;
       --surface: rgba(255, 255, 255, 0.92);
       --surface-strong: #ffffff;
       --text: #162033;
       --muted: #53607a;
       --line: #d6deeb;
       --brand: #4f6bff;
       --brand-strong: #3650dc;
       --focus: #0b57d0;
       --danger: #b42318;
       --success: #166534;
       --shadow: 0 24px 60px rgba(25, 37, 74, 0.14);
       --radius-xl: 24px;
       --radius-lg: 18px;
       --radius-md: 14px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(79, 107, 255, 0.18), transparent 36%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
     }

     a {
       color: inherit;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: #111827;
       color: #ffffff;
       transform: translateY(-180%);
       transition: transform 0.2s ease;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .page-shell {
       width: min(100%, 1120px);
       margin: 0 auto;
       padding: 2rem 1.25rem 4rem;
     }

     .hero {
       padding: 1.5rem 0 2rem;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       margin: 0 0 1rem;
       padding: 0.4rem 0.75rem;
       border-radius: 999px;
       background: rgba(79, 107, 255, 0.1);
       color: var(--brand-strong);
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 5vw, 3.4rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero p {
       max-width: 42rem;
       margin: 1rem 0 0;
       color: var(--muted);
       font-size: 1.0625rem;
       line-height: 1.7;
     }

     .layout {
       display: grid;
       gap: 1.5rem;
       align-items: start;
     }

     .card,
     .info-panel {
       border: 1px solid rgba(214, 222, 235, 0.85);
       border-radius: var(--radius-xl);
       background: var(--surface);
       backdrop-filter: blur(16px);
       box-shadow: var(--shadow);
     }

     .card {
       padding: 1.5rem;
     }

     .card-header h2,
     .info-panel h2 {
       margin: 0;
       font-size: 1.4rem;
       line-height: 1.2;
     }

     .card-header p,
     .info-panel p,
     .required-note,
     .form-help,
     .status-message {
       color: var(--muted);
       line-height: 1.6;
     }

     .card-header p,
     .info-panel p {
       margin: 0.75rem 0 0;
     }

     form {
       margin-top: 1.5rem;
     }

     .required-note {
       margin: 0 0 1rem;
       font-size: 0.95rem;
     }

     .form-field {
       margin: 0 0 1.5rem;
     }

     fieldset {
       margin: 0;
       padding: 1.25rem;
       border: 1px solid var(--line);
       border-radius: var(--radius-lg);
       background: var(--surface-strong);
     }

     legend {
       padding: 0 0.35rem;
       font-size: 1.05rem;
       font-weight: 700;
     }

     .required-indicator {
       color: var(--danger);
       font-weight: 800;
     }

     .form-help,
     .form-error {
       margin: 0.25rem 0 0;
       font-size: 0.95rem;
     }

     .form-error {
       color: var(--danger);
       font-weight: 700;
     }

     .radio-list {
       display: grid;
       gap: 0.875rem;
       margin-top: 1rem;
     }

     .radio-option {
       position: relative;
     }

     .radio-option input[type="radio"] {
       position: absolute;
       inset: 0;
       opacity: 0;
       margin: 0;
     }

     .radio-option label {
       display: flex;
       align-items: center;
       gap: 1rem;
       min-height: 3.75rem;
       padding: 1rem 1rem 1rem 1.1rem;
       border: 1px solid var(--line);
       border-radius: var(--radius-md);
       background: #ffffff;
       color: var(--text);
       font-weight: 600;
       cursor: pointer;
       transition:
         border-color 0.2s ease,
         background-color 0.2s ease,
         box-shadow 0.2s ease,
         transform 0.2s ease;
     }

     .radio-option label::before {
       content: "";
       flex: 0 0 auto;
       width: 1.2rem;
       height: 1.2rem;
       border: 2px solid #7a879d;
       border-radius: 50%;
       background: #ffffff;
       box-shadow: inset 0 0 0 0.24rem #ffffff;
       transition: border-color 0.2s ease, background-color 0.2s ease;
     }

     .radio-option input[type="radio"]:checked + label {
       border-color: rgba(79, 107, 255, 0.75);
       background: rgba(79, 107, 255, 0.08);
       box-shadow: 0 12px 32px rgba(79, 107, 255, 0.12);
     }

     .radio-option input[type="radio"]:checked + label::before {
       border-color: var(--brand);
       background: var(--brand);
     }

     .radio-option input[type="radio"]:focus-visible + label,
     .submit-button:focus-visible,
     .skip-link:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .submit-button {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       min-height: 3.25rem;
       padding: 0.95rem 1.3rem;
       border: 0;
       border-radius: 999px;
       background: linear-gradient(135deg, var(--brand) 0%, var(--brand-strong) 100%);
       color: #ffffff;
       font-size: 1rem;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 18px 28px rgba(54, 80, 220, 0.26);
     }

     .submit-button:hover {
       transform: translateY(-1px);
     }

     .status-message {
       min-height: 1.75rem;
       margin: 1rem 0 0;
       font-weight: 600;
     }

     .status-message[data-state="error"] {
       color: var(--danger);
     }

     .status-message[data-state="success"] {
       color: var(--success);
     }

     .info-panel {
       padding: 1.5rem;
     }

     .info-list {
       display: grid;
       gap: 0.9rem;
       margin: 1rem 0 0;
       padding: 0;
       list-style: none;
     }

     .info-list li {
       padding: 0.95rem 1rem;
       border-radius: var(--radius-md);
       background: rgba(255, 255, 255, 0.75);
       color: var(--muted);
     }

     @media (min-width: 860px) {
       .layout {
         grid-template-columns: minmax(0, 1.4fr) minmax(16rem, 0.85fr);
       }

       .card,
       .info-panel {
         padding: 2rem;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
         scroll-behavior: auto !important;
         transition-duration: 0.01ms !important;
       }
     }

     @media (forced-colors: active) {
       .card,
       .info-panel,
       fieldset,
       .radio-option label,
       .submit-button,
       .eyebrow {
         border: 1px solid CanvasText;
         background: Canvas;
         box-shadow: none;
       }

       .radio-option label::before {
         border-color: CanvasText;
         background: Canvas;
       }

       .radio-option input[type="radio"]:checked + label::before {
         background: Highlight;
         border-color: Highlight;
       }
     }
   </style>
 </head>
 <body>
   <div id="app"></div>

   <script>
     const options = [
       { id: "notification-email", value: "Email", label: "Email" },
       { id: "notification-sms", value: "SMS", label: "SMS" },
       { id: "notification-push", value: "Push Notifications", label: "Push Notifications" }
     ];

     function PageShell(content) {
       return `
         <a class="skip-link" href="#maincontent">Skip to main content</a>
         <header class="page-shell hero">
           <p class="eyebrow">Preferences</p>
         </header>
         <main id="maincontent" tabindex="-1" class="page-shell">
           ${content}
         </main>
       `;
     }

     function RadioOption(option) {
       return `
         <div class="radio-option">
           <input
             id="${option.id}"
             type="radio"
             name="notificationPreference"
             value="${option.value}"
             required
           >
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     function NotificationQuestion() {
       return `
         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-indicator" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="form-help">
               Select one option to choose how account updates and alerts should reach you.
             </p>
             <div class="radio-list">
               ${options.map(RadioOption).join("")}
             </div>
             <p id="notification-error" class="form-error" hidden>
               Error: Select how you prefer to receive notifications.
             </p>
           </fieldset>
         </div>
       `;
     }

     function FormCard() {
       return `
         <section class="card" aria-labelledby="form-title">
           <div class="card-header">
             <h1 id="form-title">Notification settings</h1>
             <p>Choose a single delivery channel for product news, reminders, and important updates.</p>
           </div>
           <form id="preferences-form" novalidate>
             <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required field</p>
             ${NotificationQuestion()}
             <button class="submit-button" type="submit">Save preference</button>
             <p id="form-status" class="status-message" aria-live="polite"></p>
           </form>
         </section>
       `;
     }

     function InfoPanel() {
       return `
         <aside class="info-panel" aria-labelledby="details-title">
           <h2 id="details-title">What happens next</h2>
           <p>Your selected channel becomes the default for future account messages.</p>
           <ul class="info-list">
             <li>Email works well for summaries and account receipts.</li>
             <li>SMS is ideal for urgent alerts while you're on the go.</li>
             <li>Push notifications keep updates visible inside the app experience.</li>
           </ul>
         </aside>
       `;
     }

     function App() {
       return PageShell(`
         <div class="layout">
           ${FormCard()}
           ${InfoPanel()}
         </div>
       `);
     }

     function setGroupInvalidState(isInvalid) {
       document.querySelectorAll('input[name="notificationPreference"]').forEach((radio) => {
         if (isInvalid) {
           radio.setAttribute("aria-invalid", "true");
         } else {
           radio.removeAttribute("aria-invalid");
         }
       });
     }

     function updateGroupDescription(showError) {
       const fieldset = document.getElementById("notification-group");
       fieldset.setAttribute(
         "aria-describedby",
         showError ? "notification-help notification-error" : "notification-help"
       );
     }

     function showError() {
       const error = document.getElementById("notification-error");
       const status = document.getElementById("form-status");
       error.hidden = false;
       updateGroupDescription(true);
       status.textContent = "Please choose one notification method before saving.";
       status.dataset.state = "error";
       setGroupInvalidState(true);
       const firstRadio = document.querySelector('input[name="notificationPreference"]');
       if (firstRadio) {
         firstRadio.focus();
       }
     }

     function clearError() {
       const error = document.getElementById("notification-error");
       if (!error.hidden) {
         error.hidden = true;
       }
       updateGroupDescription(false);
       setGroupInvalidState(false);
     }

     function showSuccess(value) {
       const status = document.getElementById("form-status");
       status.textContent = `Preference saved: ${value}.`;
       status.dataset.state = "success";
     }

     function bindForm() {
       const form = document.getElementById("preferences-form");
       const radios = document.querySelectorAll('input[name="notificationPreference"]');

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           clearError();
           const status = document.getElementById("form-status");
           status.textContent = "";
           status.dataset.state = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = document.querySelector('input[name="notificationPreference"]:checked');

         if (!selected) {
           showError();
           return;
         }

         clearError();
         showSuccess(selected.value);
       });
     }

     document.getElementById("app").innerHTML = App();
     bindForm();
   </script>
 </body>
 </html>

')
